def __init__(self, format, extra_types=None, case_sensitive=False):
    # Validate that braces are properly matched
    brace_depth = 0
    i = 0
    while i < len(format):
        if format[i] == '\\' and i + 1 < len(format) and format[i+1] in '{}':
            # escaped brace - skip both characters
            i += 2
            continue
        elif format[i] == '{':
            brace_depth += 1
        elif format[i] == '}':
            if brace_depth <= 0:
                raise ValueError("Unmatched '}' in format string")
            brace_depth -= 1
        i += 1
    if brace_depth > 0:
        raise ValueError("Missing closing '}' in format string")
